export interface IdentifyResult {
  species: string;
  confidence: number;
}

export async function identifyPlant(
  baseUrl: string,
  image: Blob,
  attempts = 5,
): Promise<IdentifyResult> {
  let lastError: unknown;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      const response = await fetch(`${baseUrl}/identify`, {
        method: "POST",
        body: image,
      });
      if (!response.ok) {
        throw new Error(`identify failed: ${response.status}`);
      }
      return (await response.json()) as IdentifyResult;
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError;
}
